148	// Each failure names the theme, the colour, the surface and the measured ratio.
149	func TestEveryTextColourReachesItsContrastOnEveryTheme(t *testing.T) {
150		eachShippedTheme(t, func(t *testing.T, name string) {
151			for _, ink := range textInks() {
152				for _, need := range ink.on {
153					fg, bg := ink.fg(), need.bg()
154					ratio, err := ContrastRatio(fg, bg)
155					if err != nil {
156						t.Errorf("theme %s: %s on %s: %v", name, ink.what, need.surface, err)
157						continue
158					}
159					if ratio < need.min {
160						t.Errorf("theme %s: %s %s on %s %s is %.2f:1, want >= %.1f:1",
161							name, ink.what, Hex(fg), need.surface, Hex(bg), ratio, need.min)
162					}
163				}
164			}
165		})
166	}
167	
168	// Each failure names the theme, the pair, both colours and the measured ratio.
169	func TestEveryTextPairReachesItsContrastOnEveryTheme(t *testing.T) {
170		eachShippedTheme(t, func(t *testing.T, name string) {
171			for _, p := range textPairs() {
172				fg, bg := p.get()
173				ratio, err := ContrastRatio(fg, bg)
174				if err != nil {
175					t.Errorf("theme %s: %s: %v", name, p.what, err)
176					continue
177				}
178				if ratio < p.min {
179					t.Errorf("theme %s: %s, %s (%s) on %s (%s) is %.2f:1, want >= %.1f:1",
180						name, p.what, Hex(fg), p.fgKey, Hex(bg), p.bgKey, ratio, p.min)
181				}
182			}
183		})
184	}
