186	// A greyed control still has to be read: raising ColorDim is not enough when the
187	// label sits on a background of the same hue. The disabled button used to paint
188	// ColorDim on ColorButtonInactiveBg, which is the same hex on nine themes (1:1).
189	func TestTheDisabledButtonLabelReachesTextContrastOnEveryTheme(t *testing.T) {
190		eachShippedTheme(t, func(t *testing.T, name string) {
191			for _, focused := range []bool{false, true} {
192				s := ButtonStyle(focused, "disabled")
193				fg, bg := s.GetForeground(), s.GetBackground()
194				ratio, err := ContrastRatio(fg, bg)
195				if err != nil {
196					t.Errorf("theme %s: disabled button (focused=%v): %v", name, focused, err)
197					continue
198				}
199				if ratio < textMinContrast {
200					t.Errorf("theme %s: disabled button (focused=%v) label %s on %s is %.2f:1, want >= %.1f:1",
201						name, focused, Hex(fg), Hex(bg), ratio, textMinContrast)
202				}
203			}
204		})
205	}
206	
207	// Grey says "not now", and colour alone must not be the only thing that says it
208	// (WCAG 1.4.1): a disabled button is italic, an enabled one is not, and the
209	// focus mark of a disabled button is an inversion rather than a colour only.
210	func TestTheDisabledButtonDiffersFromAnEnabledOneByMoreThanColour(t *testing.T) {
211		withTheme(t, DefaultTheme())
212		for _, focused := range []bool{false, true} {
213			dis, en := ButtonStyle(focused, "disabled"), ButtonStyle(focused, "primary")
214			if !dis.GetItalic() {
215				t.Errorf("focused=%v: the disabled button is not italic", focused)
216			}
217			if en.GetItalic() {
218				t.Errorf("focused=%v: the enabled button is italic: the signal would carry nothing", focused)
219			}
220		}
221		if on, off := ButtonStyle(true, "disabled"), ButtonStyle(false, "disabled"); sameColor(on.GetBackground(), off.GetBackground()) {
222			t.Error("a focused disabled button keeps the unfocused background: the focus would be invisible")
223		}
224	}
