226	// Rule 118: an inactive tab is ColorDim on the tab's own background. The theme
227	// files used to set tab_inactive_fg on its own, to a tone that was never held to
228	// 4.5:1 (1.4:1 on catppuccin-latte).
229	func TestTheInactiveTabLabelReachesTextContrastOnEveryTheme(t *testing.T) {
230		eachShippedTheme(t, func(t *testing.T, name string) {
231			ratio, err := ContrastRatio(ColorTabInactiveFg, ColorTabInactiveBg)
232			if err != nil {
233				t.Fatal(err)
234			}
235			if ratio < textMinContrast {
236				t.Errorf("theme %s: ColorTabInactiveFg %s on ColorTabInactiveBg %s is %.2f:1, want >= %.1f:1",
237					name, Hex(ColorTabInactiveFg), Hex(ColorTabInactiveBg), ratio, textMinContrast)
238			}
239		})
240	}
