242	// severityLevels are the levels a badge exists for. INFO and UNKNOWN share one
243	// badge (severity_info_fg on severity_info); it was left out of D181 and is held
244	// from DEVDESK-774 part A, once the correction moved its colours.
245	var severityLevels = []string{"CRITICAL", "HIGH", "MEDIUM", "LOW", "INFO", "UNKNOWN"}
246	
247	// severityBadgeKeys names the theme keys of a badge, for the failure message.
248	var severityBadgeKeys = map[string][2]string{
249		"CRITICAL": {"severity_critical_fg", "severity_critical"},
250		"HIGH":     {"severity_high_fg", "severity_high"},
251		"MEDIUM":   {"severity_medium_fg", "severity_medium"},
252		"LOW":      {"severity_low_fg", "severity_low"},
253		"INFO":     {"severity_info_fg", "severity_info"},
254		"UNKNOWN":  {"severity_info_fg", "severity_info"},
255	}
