257	// DEVDESK-770 part B (D181). A severity badge is the selected row of a finding
258	// of that level: TableStylesForSeverity(level).Selected paints the level's
259	// foreground on the level's background. The ratio is read from the style the
260	// table really uses, so a badge cannot pass on a pair the screen never shows.
261	// Each failure names the theme, the level, both colours with their theme keys
262	// and the ratio.
263	func TestEverySeverityBadgeReachesTextContrastOnEveryTheme(t *testing.T) {
264		eachShippedTheme(t, func(t *testing.T, name string) {
265			for _, level := range severityLevels {
266				sel := TableStylesForSeverity(level).Selected
267				fg, bg := sel.GetForeground(), sel.GetBackground()
268				ratio, err := ContrastRatio(fg, bg)
269				if err != nil {
270					t.Errorf("theme %s: %s badge: %v", name, level, err)
271					continue
272				}
273				if ratio < textMinContrast {
274					keys := severityBadgeKeys[level]
275					t.Errorf("theme %s: %s badge, %s (%s) on %s (%s) is %.2f:1, want >= %.1f:1",
276						name, level, Hex(fg), keys[0], Hex(bg), keys[1], ratio, textMinContrast)
277				}
278			}
279			// ColorFooterError and ColorFooterWarn alias the CRITICAL and MEDIUM badge
280			// backgrounds, so the badge foregrounds have to read on them too.
281			aliased := []struct {
282				what   string
283				fg, bg color.Color
284			}{
285				{"CRITICAL badge (ColorSeverityCriticalFg on ColorFooterError)", ColorSeverityCriticalFg, ColorFooterError},
286				{"MEDIUM badge (ColorSeverityMediumFg on ColorFooterWarn)", ColorSeverityMediumFg, ColorFooterWarn},
287			}
288			for _, p := range aliased {
289				ratio, err := ContrastRatio(p.fg, p.bg)
290				if err != nil {
291					t.Errorf("theme %s: %s: %v", name, p.what, err)
292					continue
293				}
294				if ratio < textMinContrast {
295					t.Errorf("theme %s: %s, %s on %s is %.2f:1, want >= %.1f:1",
296						name, p.what, Hex(p.fg), Hex(p.bg), ratio, textMinContrast)
297				}
298			}
299		})
300	}
