302	// The text of a badge is the application background, on every level and every
303	// theme: a light badge carries dark text and a dark one light text, which is
304	// what CRITICAL and MEDIUM already do. It makes the foreground follow the
305	// theme's own surface instead of a tone nobody holds to a ratio, and it leaves
306	// one number to move per badge (its background). INFO is left out: its badge is
307	// not part of D181.
308	func TestSeverityBadgeTextIsTheAppBackgroundOnEveryTheme(t *testing.T) {
309		eachShippedTheme(t, func(t *testing.T, name string) {
310			badges := []struct {
311				level string
312				fg    color.Color
313			}{
314				{"CRITICAL", ColorSeverityCriticalFg},
315				{"HIGH", ColorSeverityHighFg},
316				{"MEDIUM", ColorSeverityMediumFg},
317				{"LOW", ColorSeverityLowFg},
318			}
319			for _, b := range badges {
320				if Hex(b.fg) != Hex(ColorBackground) {
321					t.Errorf("theme %s: %s badge text is %s, want ColorBackground %s",
322						name, b.level, Hex(b.fg), Hex(ColorBackground))
323				}
324			}
325		})
326	}
