328	// minSeverityGap is the smallest CIE76 distance CRITICAL and HIGH keep on a
329	// shipped theme. Measured on 2026-11-24 before part B: the closest pair is
330	// catppuccin-macchiato at 8.9 (frappe 11.3, latte 11.7, mocha and default
331	// 14.1); raising HIGH to 4.5:1 moves latte from 11.7 to 9.0 and leaves the
332	// others within 1.6 of their value. The bar is 8, a little under the tightest
333	// measured pair: it catches a HIGH pulled onto CRITICAL to reach a contrast,
334	// not the palettes' own closeness, and the word on the badge (see
335	// TestTheSeverityCellSpellsTheLevelOut) is the other carrier.
336	const minSeverityGap = 8.0
337	
338	func TestSeverityHighAndCriticalStayApart(t *testing.T) {
339		eachShippedTheme(t, func(t *testing.T, name string) {
340			d, err := ColorDistance(ColorSeverityCritical, ColorSeverityHigh)
341			if err != nil {
342				t.Fatal(err)
343			}
344			if d < minSeverityGap {
345				t.Errorf("theme %s: CRITICAL %s and HIGH %s are delta E %.1f apart, want >= %.1f",
346					name, Hex(ColorSeverityCritical), Hex(ColorSeverityHigh), d, minSeverityGap)
347			}
348		})
349	}
