351	// A theme written before severity_low existed, or by hand, may leave both LOW
352	// keys out. The fallback pair has to stay readable. Since D181 the fallbacks are
353	// ColorDim for the background and ColorBackground for the text, the same pair a
354	// shipped dark theme sets: ColorDim is held to 4.5:1 on the background, so the
355	// pair reads on every theme. (D177 had ColorCmdLineBg and ColorText, because
356	// ColorDim was then a light text tone under a light ColorText, about 2:1.)
357	func TestAThemeWithoutSeverityLowKeepsAReadableLowBadge(t *testing.T) {
358		for name, th := range shippedThemes(t) {
359			t.Run(name, func(t *testing.T) {
360				bare := *th
361				bare.SeverityLow, bare.SeverityLowFg = "", ""
362				withTheme(t, &bare)
363				ratio, err := ContrastRatio(ColorSeverityLowFg, ColorSeverityLow)
364				if err != nil {
365					t.Fatal(err)
366				}
367				if ratio < textMinContrast {
368					t.Errorf("theme %s without severity_low: %s on %s is %.2f:1, want >= %.1f:1",
369						name, Hex(ColorSeverityLowFg), Hex(ColorSeverityLow), ratio, textMinContrast)
370				}
371			})
372		}
373	}
