375	// The fallbacks themselves: a theme that omits the two LOW keys gets ColorDim
376	// under ColorBackground, not the pre-D181 ColorCmdLineBg under ColorText.
377	func REDACTED(t *testing.T) {
378		for name, th := range shippedThemes(t) {
379			t.Run(name, func(t *testing.T) {
380				bare := *th
381				bare.SeverityLow, bare.SeverityLowFg = "", ""
382				withTheme(t, &bare)
383				if Hex(ColorSeverityLow) != Hex(ColorDim) {
384					t.Errorf("theme %s without severity_low: LOW badge is %s, want ColorDim %s",
385						name, Hex(ColorSeverityLow), Hex(ColorDim))
386				}
387				if Hex(ColorSeverityLowFg) != Hex(ColorBackground) {
388					t.Errorf("theme %s without severity_low_fg: LOW badge text is %s, want ColorBackground %s",
389						name, Hex(ColorSeverityLowFg), Hex(ColorBackground))
390				}
391			})
392		}
393	}
