255	func TestMinimalToneIsMinimal(t *testing.T) {
256		bg := rgb(30, 30, 46)
257		fg := rgb(88, 91, 112)
258		got, _, err := minimalTone(fg, []color.Color{bg}, 4.5)
259		if err != nil {
260			t.Fatal(err)
261		}
262		h, s, l, _ := toHSL(got)
263		// One step less must not hold, or the move was larger than needed.
264		prev := fromHSL(h, s, l-toneStep)
265		if r, _ := ContrastRatio(prev, bg); r >= 4.5 {
266			t.Errorf("one step earlier (%s) already holds at %.2f:1", Hex(prev), r)
267		}
268	}
