270	func TestMinimalPair(t *testing.T) {
271		cases := []struct {
272			name   string
273			fg, bg color.Color
274			min    float64
275		}{
276			{"already passes", rgb(255, 255, 255), rgb(0, 0, 0), 4.5},
277			{"low pair", rgb(130, 140, 160), rgb(100, 110, 130), 4.5},
278			{"same colour", rgb(120, 120, 120), rgb(120, 120, 120), 4.5},
279		}
280		for _, c := range cases {
281			t.Run(c.name, func(t *testing.T) {
282				nf, nb, de, err := minimalPair(c.fg, c.bg, c.min)
283				if err != nil {
284					t.Fatal(err)
285				}
286				if r, _ := ContrastRatio(nf, nb); r < c.min {
287					t.Errorf("%s on %s is %.2f:1, want >= %.1f:1", Hex(nf), Hex(nb), r, c.min)
288				}
289				if nf != c.fg && nb != c.bg {
290					t.Error("both colours moved: only one may")
291				}
292				_, df, errF := minimalTone(c.fg, []color.Color{c.bg}, c.min)
293				_, db, errB := minimalTone(c.bg, []color.Color{c.fg}, c.min)
294				best := math.Inf(1)
295				if errF == nil {
296					best = math.Min(best, df)
297				}
298				if errB == nil {
299					best = math.Min(best, db)
300				}
301				if de > best+1e-9 {
302					t.Errorf("ΔE %.2f, but moving one side costs %.2f", de, best)
303				}
304			})
305		}
306	}
