327	// TestSuggestTones prints, for every failing colour of every theme, the key to
328	// change, the colour before and after, and the delta E of the move. It asserts
329	// nothing and is skipped unless DEVDESK_THEME_TUNE=1; run it with -v:
330	//
331	//	DEVDESK_THEME_TUNE=1 go test ./internal/ui/theme/ -run TestSuggestTones -v -count=1
332	//
333	// A single colour is moved against all of its surfaces at once. Keys that other
334	// colours fall back to (color_secondary, color_primary) also move those: check
335	// the lines of the same theme together.
336	func TestSuggestTones(t *testing.T) {
337		if os.Getenv("DEVDESK_THEME_TUNE") != "1" {
338			t.Skip("set DEVDESK_THEME_TUNE=1 to print the suggested tones")
339		}
340		themes := shippedThemes(t)
341		eachShippedTheme(t, func(t *testing.T, name string) {
342			th := themes[name]
343			for _, ink := range textInks() {
344				fg := ink.fg()
345				reqs := make([]toneReq, 0, len(ink.on))
346				failing := false
347				for _, need := range ink.on {
348					reqs = append(reqs, toneReq{need.bg(), need.min})
349					if r, err := ContrastRatio(fg, need.bg()); err != nil || r < need.min {
350						failing = true
351					}
352				}
353				if !failing {
354					continue
355				}
356				after, de, err := minimalToneFor(fg, reqs)
357				if err != nil {
358					t.Logf("TUNE | %s | %s (%s) | %s | NO SOLUTION: %v", name, ink.what, ink.key, Hex(fg), err)
359					continue
360				}
361				t.Logf("TUNE | %s | %s (%s) | %s -> %s | dE %.1f | %s", name, ink.what, ink.key, Hex(fg), Hex(after), de, themeKeyState(th, ink.key))
362			}
363			for _, p := range textPairs() {
364				fg, bg := p.get()
365				if r, err := ContrastRatio(fg, bg); err == nil && r >= p.min {
366					continue
367				}
368				nf, nb, de, err := minimalPair(fg, bg, p.min)
369				if err != nil {
370					t.Logf("TUNE | %s | %s | %s on %s | NO SOLUTION: %v", name, p.what, Hex(fg), Hex(bg), err)
371					continue
372				}
373				if nf != fg {
374					t.Logf("TUNE | %s | %s (%s) | %s -> %s | dE %.1f | %s | on %s", name, p.what, p.fgKey, Hex(fg), Hex(nf), de, themeKeyState(th, p.fgKey), Hex(bg))
375				} else {
376					t.Logf("TUNE | %s | %s (%s) | %s -> %s | dE %.1f | %s | under %s", name, p.what, p.bgKey, Hex(bg), Hex(nb), de, themeKeyState(th, p.bgKey), Hex(fg))
377				}
378			}
379		})
380	}
