13	// Tuning helpers for DEVDESK-770. They compute, for a colour that misses its
14	// contrast, the smallest move that reaches it: the same hue and HSL saturation,
15	// the lightness moved by steps of 0.005 away from the surfaces, until every
16	// surface holds. They change no colour of the palette; TestSuggestTones prints
17	// the proposal so it can be copied into themes/*.json and DefaultTheme.
18	
19	// toneStep is the lightness step (HSL, 0 to 1) the search moves by.
20	const toneStep = 0.005
21	
22	// errToneUnreachable says no lightness of that hue and saturation reaches the
23	// contrast on every surface.
24	var errToneUnreachable = errors.New("no lightness reaches the contrast on every surface")
25	
26	// toneReq is one surface a colour has to hold against, and the ratio it needs.
27	type toneReq struct {
28		bg  color.Color
29		min float64
30	}
31	
32	// rgb builds an opaque colour from decimal components (no hex literal).
33	func rgb(r, g, b uint8) color.RGBA { return color.RGBA{R: r, G: g, B: b, A: 255} }
34	
35	// toHSL returns hue in degrees [0, 360), saturation and lightness in [0, 1].
36	func toHSL(c color.Color) (h, s, l float64, err error) {
37		v, err := rgb8(c, "tone")
38		if err != nil {
39			return 0, 0, 0, err
40		}
41		r, g, b := float64(v[0])/255, float64(v[1])/255, float64(v[2])/255
42		hi, lo := math.Max(r, math.Max(g, b)), math.Min(r, math.Min(g, b))
43		l = (hi + lo) / 2
44		d := hi - lo
45		if d == 0 {
46			return 0, 0, l, nil
47		}
48		s = d / (1 - math.Abs(2*l-1))
49		switch hi {
50		case r:
51			h = math.Mod((g-b)/d, 6)
52		case g:
53			h = (b-r)/d + 2
54		default:
55			h = (r-g)/d + 4
56		}
57		h *= 60
58		if h < 0 {
59			h += 360
60		}
61		return h, s, l, nil
62	}
63	
64	// fromHSL is the inverse of toHSL, rounded to 8 bits.
65	func fromHSL(h, s, l float64) color.RGBA {
66		c := (1 - math.Abs(2*l-1)) * s
67		x := c * (1 - math.Abs(math.Mod(h/60, 2)-1))
68		m := l - c/2
69		var r, g, b float64
70		switch {
71		case h < 60:
72			r, g, b = c, x, 0
73		case h < 120:
74			r, g, b = x, c, 0
75		case h < 180:
76			r, g, b = 0, c, x
77		case h < 240:
78			r, g, b = 0, x, c
79		case h < 300:
80			r, g, b = x, 0, c
81		default:
82			r, g, b = c, 0, x
83		}
84		to8 := func(v float64) uint8 { return uint8(math.Round(math.Min(math.Max((v+m)*255, 0), 255))) }
85		return rgb(to8(r), to8(g), to8(b))
86	}
87	
88	// holdsAll reports whether c reaches every requirement.
89	func holdsAll(c color.Color, reqs []toneReq) (bool, error) {
90		for _, r := range reqs {
91			ratio, err := ContrastRatio(c, r.bg)
92			if err != nil {
93				return false, err
94			}
95			if ratio < r.min {
96				return false, nil
97			}
98		}
99		return true, nil
100	}
101	
102	// minimalToneFor moves fg's lightness, away from the surfaces, by the smallest
103	// number of toneStep steps that reaches every requirement. It returns the new
104	// colour and its CIE76 distance to fg (0 when fg already holds). "Away" is up
105	// when fg is lighter than the mean luminance of the surfaces, down otherwise.
106	func minimalToneFor(fg color.Color, reqs []toneReq) (color.Color, float64, error) {
107		if ok, err := holdsAll(fg, reqs); err != nil {
108			return nil, 0, err
109		} else if ok {
110			return fg, 0, nil
111		}
112		h, s, l, err := toHSL(fg)
113		if err != nil {
114			return nil, 0, err
115		}
116		lf, err := relativeLuminance(fg)
117		if err != nil {
118			return nil, 0, err
119		}
120		var mean float64
121		for _, r := range reqs {
122			lb, err := relativeLuminance(r.bg)
123			if err != nil {
124				return nil, 0, err
125			}
126			mean += lb / float64(len(reqs))
127		}
128		dir := -1.0
129		if lf >= mean {
130			dir = 1
131		}
132		// Away from the surfaces first; the other way only when that cannot reach
133		// the contrast (a mid-tone surface, or one on each side).
134		for _, d := range []float64{dir, -dir} {
135			if cand, ok, err := walkTone(h, s, l, d, reqs); err != nil {
136				return nil, 0, err
137			} else if ok {
138				de, err := ColorDistance(fg, cand)
139				return cand, de, err
140			}
141		}
142		return nil, 0, errToneUnreachable
143	}
144	
145	// walkTone moves the lightness from l by toneStep in direction dir until every
146	// requirement holds, and reports false when it runs out of lightness first.
147	func walkTone(h, s, l, dir float64, reqs []toneReq) (color.Color, bool, error) {
148		for i := 1; ; i++ {
149			nl := l + dir*float64(i)*toneStep
150			last := nl <= 0 || nl >= 1
151			nl = math.Min(math.Max(nl, 0), 1)
152			cand := fromHSL(h, s, nl)
153			if ok, err := holdsAll(cand, reqs); err != nil {
154				return nil, false, err
155			} else if ok {
156				return cand, true, nil
157			}
158			if last {
159				return nil, false, nil
160			}
161		}
162	}
163	
164	// minimalTone is minimalToneFor with one ratio for every surface.
165	func minimalTone(fg color.Color, bgs []color.Color, min float64) (color.Color, float64, error) {
166		reqs := make([]toneReq, len(bgs))
167		for i, b := range bgs {
168			reqs[i] = toneReq{b, min}
169		}
170		return minimalToneFor(fg, reqs)
171	}
172	
173	// minimalPair reaches min between fg and bg by moving the text or the surface,
174	// whichever costs the smaller delta E. It returns both colours (one unchanged)
175	// and the distance moved.
176	func minimalPair(fg, bg color.Color, min float64) (color.Color, color.Color, float64, error) {
177		nf, df, errF := minimalTone(fg, []color.Color{bg}, min)
178		nb, db, errB := minimalTone(bg, []color.Color{fg}, min)
179		switch {
180		case errF != nil && errB != nil:
181			return nil, nil, 0, errF
182		case errB != nil || (errF == nil && df <= db):
183			return nf, bg, df, nil
184		default:
185			return fg, nb, db, nil
186		}
187	}
188	
189	// hueGap is the circular distance in degrees between two hues.
190	func hueGap(a, b float64) float64 {
191		d := math.Abs(a - b)
192		return math.Min(d, 360-d)
193	}
