292				_, df, errF := minimalTone(c.fg, []color.Color{c.bg}, c.min)
293				_, db, errB := minimalTone(c.bg, []color.Color{c.fg}, c.min)
294				best := math.Inf(1)
295				if errF == nil {
296					best = math.Min(best, df)
297				}
298				if errB == nil {
299					best = math.Min(best, db)
300				}
301				if de > best+1e-9 {
302					t.Errorf("ΔE %.2f, but moving one side costs %.2f", de, best)
303				}
304			})
305		}
306	}
